    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        return 'D'
    if n >= 100:
        return 'C'
    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    if opp_defects == 0:
        return 'C'
    if opp_defects >= 3 and opp_defects * 3 >= n:
        return 'D'
    if my_defects > opp_defects + 2:
        return 'C'
    if last_my == 'D' and last_opp == 'C':
        return 'C'
    return 'C'

